import{_ as a,a as t,b as o,c as r}from"./chunks/measurement_result2.D3YFY8lz.js";import{_ as s,o as n,c as i,a0 as l}from"./chunks/framework.akKRIpjQ.js";const w=JSON.parse('{"title":"02 · AI Grip Size","description":"","frontmatter":{},"headers":[],"relativePath":"guide/02-ai-grip.md","filePath":"guide/02-ai-grip.md"}'),h={name:"guide/02-ai-grip.md"};function d(p,e,u,g,c,m){return n(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_02-·-ai-grip-size" tabindex="-1">02 · AI Grip Size <a class="header-anchor" href="#_02-·-ai-grip-size" aria-label="Permalink to &quot;02 · AI Grip Size&quot;">​</a></h1><blockquote><p>Feature 1 of 4. Snap a photo of your palm → recommended grip size (Yonex L0–L5 / Wilson in fractions / Head–Prince–Babolat equivalent).</p></blockquote><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><img src="'+a+'" alt="Aiming the camera at the palm" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>Hold the phone up to your palm. The App estimates the following <strong>on-device by default (no upload)</strong>:</p><ul><li><strong>Palm length</strong> (mm)</li><li><strong>Palm width</strong> (mm)</li><li><strong>Finger count + ratios</strong> (calibration across hand shapes)</li><li>→ Recommended grip size in three systems simultaneously</li></ul><h2 id="how-to-take-an-accurate-photo" tabindex="-1">How to take an accurate photo <a class="header-anchor" href="#how-to-take-an-accurate-photo" aria-label="Permalink to &quot;How to take an accurate photo&quot;">​</a></h2><h3 id="rule-1-lay-the-hand-flat-on-an-a4-sheet-on-a-table" tabindex="-1">Rule 1: lay the hand flat on an A4 sheet on a table <a class="header-anchor" href="#rule-1-lay-the-hand-flat-on-an-a4-sheet-on-a-table" aria-label="Permalink to &quot;Rule 1: lay the hand flat on an A4 sheet on a table&quot;">​</a></h3><img src="'+t+`" alt="Hand laid flat on a sheet of paper" style="max-width:320px;border-radius:12px;margin:12px 0;"><blockquote><p>Yes, the same image doubles as the adjust-screen shot — the layout (palm up, fingers spread, on a paper outline) is exactly what you want before capture. Take the photo in roughly this pose and the AI&#39;s first guess will be very close to your hand&#39;s true anatomy.</p></blockquote><ul><li><strong>Flat surface</strong> — lay an A4 sheet of plain paper on a hard, flat table. Don&#39;t shoot in your palm or against a soft surface.</li><li><strong>Palm flat on the paper, fingers spread</strong> — your skin&#39;s contact with the paper gives the AI a crisp edge to anchor on. The A4 outline also normalises the camera distance (matches roughly a 30 cm working distance).</li><li><strong>Palm up (face the camera)</strong> — back-of-the-hand photos have very little texture for MediaPipe to anchor; palm-up photos are far more reliable.</li><li><strong>Don&#39;t curl the fingers</strong> — fingers must be extended and spaced apart, even if it feels slightly strained.</li></ul><h3 id="rule-2-even-lighting" tabindex="-1">Rule 2: even lighting <a class="header-anchor" href="#rule-2-even-lighting" aria-label="Permalink to &quot;Rule 2: even lighting&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   ✅ Good               ❌ Bad</span></span>
<span class="line"><span>┌────────────┐     ┌────────────┐</span></span>
<span class="line"><span>│  white wall│     │  messy desk │</span></span>
<span class="line"><span>│   🖐       │     │   🖐 + 📦   │</span></span>
<span class="line"><span>│            │     │            │</span></span>
<span class="line"><span>└────────────┘     └────────────┘</span></span></code></pre></div><ul><li>Light should be even and diffuse; sidelight through a window is better than a harsh ceiling lamp</li><li>Turn off the flash if the room has enough ambient light</li><li>A4 paper diffuses harsh overhead light nicely — another reason to use it</li></ul><h3 id="rule-3-phone-parallel-to-the-hand" tabindex="-1">Rule 3: phone parallel to the hand <a class="header-anchor" href="#rule-3-phone-parallel-to-the-hand" aria-label="Permalink to &quot;Rule 3: phone parallel to the hand&quot;">​</a></h3><ul><li>Don&#39;t shoot top-down / from below — straight overhead</li><li>Camera ≈ 30–50 cm above the paper</li><li>Use the <strong>rear</strong> camera (front camera has heavy distortion)</li></ul><h2 id="two-ways-to-correct-the-ai" tabindex="-1">Two ways to correct the AI <a class="header-anchor" href="#two-ways-to-correct-the-ai" aria-label="Permalink to &quot;Two ways to correct the AI&quot;">​</a></h2><p>Before walking through what the result screen looks like, here&#39;s the <strong>two adjust modes the App offers</strong> — pick whichever fits the situation:</p><h3 id="mode-1-—-fine-tune-on-the-result-page-preferred" tabindex="-1">Mode 1 — Fine-tune on the result page (preferred) <a class="header-anchor" href="#mode-1-—-fine-tune-on-the-result-page-preferred" aria-label="Permalink to &quot;Mode 1 — Fine-tune on the result page (preferred)&quot;">​</a></h3><p>This mode lets you <strong>drag the wrist crease line</strong> on the photo. The wrist crease is where the AI estimates the start of the palm; if it&#39;s 5 mm too high (toward the fingers), the recommended size jumps up.</p><ul><li>After capture, you see your hand with a <strong>horizontal line</strong> drawn at the AI&#39;s best guess for the wrist crease</li><li><strong>Long-press and drag vertically</strong> to move the line</li><li>&quot;Measurements&quot; + &quot;Sizes&quot; panels update <strong>live</strong> as you drag</li><li>Drag range is limited to ±15 mm from the AI&#39;s initial guess (prevents wild swings)</li><li>When you&#39;re happy, <code>Save to history</code></li></ul><blockquote><p>This is the mode you should use when the AI&#39;s number is in the right ballpark but slightly off (typically a 3–10 mm correction).</p></blockquote><h3 id="mode-2-—-adjust-green-frame-align-the-a4-paper-to-the-green-box" tabindex="-1">Mode 2 — Adjust Green Frame, align the A4 paper to the green box <a class="header-anchor" href="#mode-2-—-adjust-green-frame-align-the-a4-paper-to-the-green-box" aria-label="Permalink to &quot;Mode 2 — Adjust Green Frame, align the A4 paper to the green box&quot;">​</a></h3><p>If the <strong>overall scale</strong> of the result is off — e.g. you wore the wrong overgrip earlier and the photo is shrunken or stretched — switch to the <strong>adjust screen</strong> to give the App a known physical reference.</p><p>The screen is titled <strong>&quot;Adjust Green Frame&quot;</strong> and shows:</p><img src="`+t+'" alt="Adjust Green Frame — A4 paper edges sit inside the teal frame" style="max-width:320px;border-radius:12px;margin:12px 0;"><ul><li>Your full photo (palm + A4 paper)</li><li>A <strong>teal-green rectangular frame</strong> the App computes at the camera&#39;s expected working distance (~30 cm overhead)</li><li>A bottom-bar hint: <strong>&quot;Drag with one finger; pinch to zoom (rotation disabled). Fit the A4 inside the green frame, then Next.&quot;</strong></li><li>A green <strong>Next (Analyze)</strong> button</li></ul><p>What to do:</p><ul><li><strong>Drag with one finger</strong> to translate the photo so the A4 paper is centered under the frame</li><li><strong>Pinch with two fingers</strong> to scale the photo so the <strong>A4 paper&#39;s four edges line up with the green frame</strong></li><li>Try to get the four paper edges <strong>flush with the green frame</strong> — the closer they are, the more accurate the scale calibration</li><li>Rotation is <strong>disabled</strong> (so you don&#39;t have to worry about accidentally tilting the photo)</li><li>Tap <strong>Next (Analyze)</strong> to re-run the palm detection with the corrected scale</li></ul><blockquote><p>Because an A4 sheet has a known physical size (210 × 297 mm), telling the App &quot;the green frame = an A4 sheet at this distance&quot; pins down the absolute scale of the photo. This fixes overall-size errors that Mode 1 (line drag) can&#39;t reach.</p><p>Combine the two: <strong>Mode 2 for scale, Mode 1 for the start of the palm.</strong></p></blockquote><h2 id="photo-flow" tabindex="-1">Photo flow <a class="header-anchor" href="#photo-flow" aria-label="Permalink to &quot;Photo flow&quot;">​</a></h2><ol><li><code>Home</code> → <code>AI grip size</code></li><li><code>Start measurement</code> → request camera permission (first time)</li><li>Hold the phone <strong>overhead</strong> (≈ 30–50 cm above the paper). Aim at the laid-flat palm. <strong>Hold still for 1 second</strong> for pose pre-check.</li><li><code>Capture</code> (or auto-trigger)</li><li>Wait 1–2 seconds: on-device MediaPipe Hand detection → result screen</li></ol><h2 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h2><img src="'+o+'" alt="Measurement result" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>The result screen shows the AI&#39;s palm detection overlaid on your photo, side by side with the numbers:</p><table tabindex="0"><thead><tr><th>Panel</th><th>Content</th></tr></thead><tbody><tr><td><strong>Photo + overlay</strong></td><td>Your hand with the <strong>wrist crease line</strong> (the horizontal line where the palm meets the wrist) drawn by the AI</td></tr><tr><td><strong>Measurements</strong></td><td>Palm length + width in mm</td></tr><tr><td><strong>Sizes</strong></td><td>Yonex / Wilson / Head-Prince-Babolat equivalents</td></tr></tbody></table><img src="'+r+`" alt="Measurement result — three system grid" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>The three-system grid reads:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  Yonex   Wilson    Head / Prince / Babolat</span></span>
<span class="line"><span>                  L3      4½&quot;       4¾</span></span></code></pre></div><p><strong>If the line is off</strong>, use Mode 1 (drag the wrist crease line) — see <a href="#two-ways-to-correct-the-ai">Two ways to correct the AI</a> above.</p><p>If the line isn&#39;t there or the numbers look obviously wrong, tap <strong><code>Adjust scale only</code></strong> → Mode 2 adjusts.</p><h2 id="error-budget-mitigations" tabindex="-1">Error budget &amp; mitigations <a class="header-anchor" href="#error-budget-mitigations" aria-label="Permalink to &quot;Error budget &amp; mitigations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error source</th><th>Impact</th><th>Mitigation</th></tr></thead><tbody><tr><td><strong>Tilted palm</strong></td><td>±5–8 mm in length</td><td>App prompts &quot;place flat&quot;</td></tr><tr><td><strong>Lens distortion</strong> (front camera especially)</td><td>±3 mm</td><td>Default uses the rear camera</td></tr><tr><td><strong>Skin tone / lighting</strong></td><td>±2 mm keypoint drift</td><td>MediaPipe Hand 2024 model is robust across skin tones</td></tr><tr><td><strong>Hand occlusion</strong> (ring, long nails)</td><td>failure / size overshoot</td><td>Remove rings; trim nails first</td></tr><tr><td><strong>Hand-shape training bias</strong></td><td>±3 mm</td><td>Use Mode 1 (drag the crease line) or Mode 2 (adjust screen slider)</td></tr></tbody></table><blockquote><p><strong>RMSE in tests</strong>: on-device 4.2 mm. Translated to size = about <strong>±⅓ size</strong> in the Yonex system.</p></blockquote><h2 id="limits-boundaries" tabindex="-1">Limits &amp; boundaries <a class="header-anchor" href="#limits-boundaries" aria-label="Permalink to &quot;Limits &amp; boundaries&quot;">​</a></h2><ul><li>❌ <strong>Gloves not supported</strong>: gloves wipe out the keypoints</li><li>❌ <strong>Children&#39;s hands</strong>: training data is mainly adults; child hands are unreliable</li><li>❌ <strong>Extreme lighting</strong> (very dark, strong backlight): capture fails → use manual adjust</li><li>❌ <strong>Multi-person frames</strong>: App picks the largest palm (still error-prone)</li></ul><h2 id="original-photos-are-not-saved" tabindex="-1">Original photos are not saved <a class="header-anchor" href="#original-photos-are-not-saved" aria-label="Permalink to &quot;Original photos are not saved&quot;">​</a></h2><p>V1.1 <strong>does not keep the original photo</strong>. After the measurement, only the keypoint coordinate array (~80 bytes) is cached for the history view. If you need &quot;keep the photo for later recompute&quot;, enable it under <code>Settings → Data → Keep original photos</code> (off by default).</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><h3 id="does-iphone-ipad-work" tabindex="-1">Does iPhone / iPad work? <a class="header-anchor" href="#does-iphone-ipad-work" aria-label="Permalink to &quot;Does iPhone / iPad work?&quot;">​</a></h3><p>This version does not support iOS. See <a href="./00-introduction.html#supported-platforms">00 · Platforms</a>.</p><h3 id="how-much-compute-does-on-device-need" tabindex="-1">How much compute does on-device need? <a class="header-anchor" href="#how-much-compute-does-on-device-need" aria-label="Permalink to &quot;How much compute does on-device need?&quot;">​</a></h3><p>Recommended Snapdragon 7xx / Dimensity 800 or above. Low-end phones may spin for a few seconds.</p><h3 id="does-my-measurement-data-get-uploaded" tabindex="-1">Does my measurement data get uploaded? <a class="header-anchor" href="#does-my-measurement-data-get-uploaded" aria-label="Permalink to &quot;Does my measurement data get uploaded?&quot;">​</a></h3><p><strong>No</strong>. Everything runs on-device; the image never leaves your phone.</p><h3 id="i-disagree-with-the-ai-s-number-—-what-now" tabindex="-1">I disagree with the AI&#39;s number — what now? <a class="header-anchor" href="#i-disagree-with-the-ai-s-number-—-what-now" aria-label="Permalink to &quot;I disagree with the AI&#39;s number — what now?&quot;">​</a></h3><p>Two options, in order of fidelity:</p><ol><li><strong>Fine-tune on the result page</strong> — long-press the wrist crease line and drag it vertically; the measurements + sizes update live. <strong>Use this when the AI&#39;s number is in the right ballpark but slightly off</strong> (typically a 3–10 mm correction).</li><li><strong>Adjust screen</strong> — tap <code>Adjust scale only</code> on the result page → single ±10 mm slider. <strong>Use this when you already measured with a ruler and just want to type the number in</strong>, or when on-device detection failed entirely and you never saw the photo.</li></ol>`,58)])])}const y=s(h,[["render",d]]);export{w as __pageData,y as default};
